           FROM public.unions u LEFT JOIN public.union_settlement_floor f ON f.union_id=u.id
        ), union_work AS (
          SELECT u.id,LEAST(u.first_week,(SELECT min(q.period_start) FROM public.union_accounting_runs q
            WHERE q.union_id=u.id AND q.status<>'complete'
              AND (u.earliest_period_start IS NULL OR q.period_start>=u.first_week))) AS first_week
           FROM union_floors u
        ), eligible AS (
          -- Match the exact-scope floor rounding and per-week due check. An
          -- older union backlog remains due before this Monday's new close.
          SELECT 'union'::text AS kind,w.id FROM union_work w WHERE w.first_week<v_to
           AND v_now>=public.fn_union_accounting_run_at(public.fn_union_week_start(w.first_week+interval '8 days'))
          UNION ALL SELECT 'club',w.club_id FROM standalone_work w JOIN public.clubs c ON c.id=w.club_id
           WHERE c.is_union IS NOT TRUE AND w.first_week<v_to
            AND v_now>=public.fn_union_accounting_run_at(v_to) GROUP BY w.club_id
        ) SELECT e.kind,e.id,max(GREATEST(q.last_scheduler_visit_at,q.started_at)) AS last_visit
          FROM eligible e LEFT JOIN public.union_accounting_runs q ON q.scope_kind=e.kind AND q.scope_id=e.id
          GROUP BY e.kind,e.id
          ORDER BY last_visit NULLS FIRST,(e.kind='union') DESC,e.id
      LOOP
        IF v_checked>=v_attempt_budget OR clock_timestamp()-v_scheduler_started>interval '15 minutes'
          OR extract(minute FROM clock_timestamp())>=45 OR public.fn_platform_frozen() THEN
          v_more:=true;EXIT;END IF;
        -- Transaction advisory locks are reentrant. The exact child call uses
        -- this same scheduler lock and only the remaining TOTAL attempt budget.
        PERFORM set_config('app.weekly_accounting_attempt_budget',(v_attempt_budget-v_checked)::text,true);
        PERFORM set_config('app.weekly_accounting_scheduler_started',v_scheduler_started::text,true);
        v_scope_result:=public.fn_process_weekly_accounting_scope(
          CASE WHEN v_scope.kind='union' THEN v_scope.id END,
          CASE WHEN v_scope.kind='club' THEN v_scope.id END);
        IF v_scope_result->>'skipped'='true' AND v_scope_result->>'reason'='maintenance_window' THEN
          v_more:=true;EXIT;END IF;
        IF jsonb_typeof(v_scope_result->'checked') IS DISTINCT FROM 'number'
          OR jsonb_typeof(v_scope_result->'failed') IS DISTINCT FROM 'number'
          OR jsonb_typeof(v_scope_result->'detail') IS DISTINCT FROM 'array' THEN
          RAISE EXCEPTION 'weekly_scope_scheduler_receipt_invalid' USING ERRCODE='23514';END IF;
        v_scope_checked:=(v_scope_result->>'checked')::integer;v_scope_failed:=(v_scope_result->>'failed')::integer;
        IF v_scope_checked<0 OR v_scope_checked>v_attempt_budget-v_checked OR v_scope_failed<0
          OR v_scope_failed>v_scope_checked OR jsonb_array_length(v_scope_result->'detail')<>v_scope_checked
          OR v_scope_result->'checked' IS DISTINCT FROM to_jsonb(v_scope_checked)
          OR v_scope_result->'failed' IS DISTINCT FROM to_jsonb(v_scope_failed)
          OR v_scope_result->'success' IS DISTINCT FROM to_jsonb(v_scope_failed=0)
          OR (SELECT count(*) FROM jsonb_array_elements(v_scope_result->'detail')d WHERE d->'result'->'success' IS DISTINCT FROM 'true'::jsonb)<>v_scope_failed
          OR EXISTS(SELECT 1 FROM jsonb_array_elements(v_scope_result->'detail')d
            WHERE CASE WHEN v_scope.kind='union' THEN d->>'union_id' ELSE d->>'club_id' END IS DISTINCT FROM v_scope.id::text) THEN
          RAISE EXCEPTION 'weekly_scope_scheduler_receipt_invalid' USING ERRCODE='23514';END IF;
        v_checked:=v_checked+v_scope_checked;v_failed:=v_failed+v_scope_failed;
        v_results:=v_results||(v_scope_result->'detail');v_visits:=v_visits+1;
        v_more:=v_more OR COALESCE((v_scope_result->>'more_remaining')::boolean,false);
        -- Completed/zero-work scopes must move to the back too. Reuse one real
        -- run row; never change attempts, result, started_at or finished_at.
        UPDATE public.union_accounting_runs q SET last_scheduler_visit_at=clock_timestamp()
         WHERE q.scope_kind=v_scope.kind AND q.scope_id=v_scope.id
          AND (q.period_start,q.period_end)=(SELECT r.period_start,r.period_end FROM public.union_accounting_runs r
            WHERE r.scope_kind=v_scope.kind AND r.scope_id=v_scope.id ORDER BY r.period_start DESC,r.period_end DESC LIMIT 1);
      END LOOP;
      PERFORM set_config('app.weekly_accounting_attempt_budget',COALESCE(v_saved_budget,''),true);
      PERFORM set_config('app.weekly_accounting_scheduler_started',COALESCE(v_saved_started,''),true);
    EXCEPTION WHEN OTHERS THEN
      PERFORM set_config('app.weekly_accounting_attempt_budget',COALESCE(v_saved_budget,''),true);
      PERFORM set_config('app.weekly_accounting_scheduler_started',COALESCE(v_saved_started,''),true);
      RAISE;
    END;
    RETURN jsonb_build_object('success',v_failed=0,'checked',v_checked,'failed',v_failed,
      'visited_scopes',v_visits,'more_remaining',v_more,'observed_at',clock_timestamp(),'detail',v_results);
  END IF;

  FOR v_union IN SELECT u.id, f.earliest_period_start$fair_dispatch$,
 $original_dispatch$  FOR v_union IN SELECT u.id, f.earliest_period_start$original_dispatch$,1,1),
 ($fair_history$      IF clock_timestamp()-v_scheduler_started>interval '15 minutes'
        OR extract(minute FROM clock_timestamp())>=45 OR public.fn_platform_frozen() THEN
        RETURN jsonb_build_object('success',v_failed=0,'checked',v_checked,'failed',v_failed,
          'more_remaining',true,'detail',v_results);
      END IF;
      PERFORM pg_advisory_xact_lock(hashtextextended('union-accounting:'||v_union.id$fair_history$,
 $original_history$      PERFORM pg_advisory_xact_lock(hashtextextended('union-accounting:'||v_union.id$original_history$,1,2),
 ($fair_union$    SELECT LEAST(v_first,min(q.period_start)) INTO v_first
      FROM public.union_accounting_runs q WHERE q.union_id=v_union.id AND q.status<>'complete'
        AND (v_union.earliest_period_start IS NULL OR q.period_start>=v_first);
    v_from := v_first;$fair_union$,$original_union$    v_from := v_first;$original_union$,1,3),
 ($fair_club$         WHERE q.standalone_club_id IS NOT NULL AND q.status<>'complete'
        UNION ALL SELECT q.standalone_club_id,q.period_start FROM public.union_accounting_runs q
         WHERE q.standalone_club_id IS NOT NULL AND q.status='complete' AND q.period_end<v_to
          AND NOT EXISTS(SELECT 1 FROM public.union_accounting_runs later
            WHERE later.standalone_club_id=q.standalone_club_id AND later.period_end>q.period_end)
        UNION ALL SELECT rp.club_id$fair_club$,
 $original_club$         WHERE q.standalone_club_id IS NOT NULL AND q.status<>'complete'
        UNION ALL SELECT rp.club_id$original_club$,1,4),
 ($fair_declarations$  v_attempt_budget integer := LEAST(8,COALESCE(NULLIF(current_setting('app.weekly_accounting_attempt_budget',true),'')::integer,8));
  v_scheduler_started timestamptz := LEAST(clock_timestamp(),COALESCE(NULLIF(current_setting('app.weekly_accounting_scheduler_started',true),'')::timestamptz,clock_timestamp()));
  v_scope record;v_scope_result jsonb;v_scope_checked integer;v_scope_failed integer;
  v_saved_budget text;v_saved_started text;v_more boolean:=false;v_visits integer:=0;
  v_stage2 jsonb;$fair_declarations$,$original_declarations$  v_stage2 jsonb;$original_declarations$,1,5),
 ($fair_budget$v_checked>=v_attempt_budget OR clock_timestamp()-v_scheduler_started>interval '15 minutes'$fair_budget$,
 $original_budget$v_checked>=8 OR clock_timestamp()-v_now>interval '15 minutes'$original_budget$,2,6),
 ($pnl_skip$      IF v_complete AND v_orphans=0 AND v_previous->>'success'='true' AND v_previous->>'accounting_version'='3'
        AND public.fn_union_pnl_close_quality(v_union.id,v_from,v_end)->>'status'='ready' THEN$pnl_skip$,
 $original_skip$      IF v_complete AND v_orphans=0 AND v_previous->>'success'='true' AND v_previous->>'accounting_version'='3' THEN$original_skip$,1,7)
 ) AS reversals(installed_text,previous_text,occurrences,ordinal) ORDER BY ordinal
 LOOP
  IF length(reconstructed)-length(replace(reconstructed,change.installed_text,''))
    <> length(change.installed_text)*change.occurrences THEN
   RAISE EXCEPTION 'standalone_timing_function_preimage_changed';
  END IF;
  reconstructed:=replace(reconstructed,change.installed_text,change.previous_text);
 END LOOP;
 IF md5(reconstructed) IS DISTINCT FROM '63f8248cd6d804f450a0b8f0fbc05e77' THEN
  RAISE EXCEPTION 'standalone_timing_function_preimage_changed';END IF;

 replacement:=definition;
 FOR change IN SELECT * FROM (VALUES
 ($old_outer$  IF p_union_id IS NULL AND v_now>=public.fn_union_accounting_run_at(v_to) THEN$old_outer$,
 $new_outer$  IF p_union_id IS NULL THEN$new_outer$,1),
 ($old_eligibility$          UNION ALL SELECT 'club',w.club_id FROM standalone_work w JOIN public.clubs c ON c.id=w.club_id
           WHERE c.is_union IS NOT TRUE AND w.first_week<v_to
            AND v_now>=public.fn_union_accounting_run_at(v_to) GROUP BY w.club_id$old_eligibility$,
 $new_eligibility$          UNION ALL SELECT 'club',w.club_id FROM standalone_work w JOIN public.clubs c ON c.id=w.club_id
           WHERE c.is_union IS NOT TRUE AND w.first_week<v_to
            AND v_now>=public.fn_union_accounting_run_at(public.fn_union_week_start(w.first_week+interval '8 days')) GROUP BY w.club_id$new_eligibility$,2),
 ($old_attempt$        INSERT INTO public.union_accounting_runs(standalone_club_id,period_start,period_end,scheduled_at,status,attempts,started_at)$old_attempt$,
 $new_attempt$        -- A source writer may have held this period lock across the deadline,
        -- maintenance announcement or a freeze change. Recheck after the lock
        -- and completion reads before creating a new financial attempt.
        IF v_checked>=v_attempt_budget OR clock_timestamp()-v_scheduler_started>interval '15 minutes'
          OR extract(minute FROM clock_timestamp())>=45 OR public.fn_platform_frozen() THEN
          RETURN jsonb_build_object('success',v_failed=0,'checked',v_checked,'failed',v_failed,'more_remaining',true,'detail',v_results);
        END IF;
        INSERT INTO public.union_accounting_runs(standalone_club_id,period_start,period_end,scheduled_at,status,attempts,started_at)$new_attempt$,3)
 ) AS patches(old_text,new_text,ordinal) ORDER BY ordinal
 LOOP
  IF length(replacement)-length(replace(replacement,change.old_text,''))<>length(change.old_text) THEN
   RAISE EXCEPTION 'standalone_timing_patch_anchor_changed';END IF;
  previous_step:=replacement;
  replacement:=replace(replacement,change.old_text,change.new_text);
  IF replace(replacement,change.new_text,change.old_text) IS DISTINCT FROM previous_step THEN
   RAISE EXCEPTION 'standalone_timing_patch_not_reversible';END IF;
 END LOOP;
 EXECUTE replacement;
END $timing_successor$;

REVOKE ALL ON FUNCTION public.fn_process_weekly_accounting_scope(uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;

-- Component 20260914163000_canonical_cron_wakes_on_the_hour.sql
-- SOURCE-ONLY PROPOSAL. UNRUN. Existing job only; no second timer or payer.
-- Follow captured transition 00 before sealed155500, the remaining sealed
-- components, union continuation and timing01 in the same atomic bundle.

SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='30s';
DO $cron_source_guard$
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'serializable' THEN
  RAISE EXCEPTION 'accounting_cron_requires_serializable' USING ERRCODE='25000';END IF;
 IF current_setting('server_version_num')::integer NOT BETWEEN 170000 AND 179999
  OR NOT EXISTS(SELECT 1 FROM pg_depend d JOIN pg_extension e ON e.oid=d.refobjid
    WHERE e.extname='pg_cron' AND d.classid='pg_class'::regclass
     AND d.objid=to_regclass('cron.job') AND d.deptype='e')
  OR NOT EXISTS(SELECT 1 FROM pg_depend d JOIN pg_extension e ON e.oid=d.refobjid
    WHERE e.extname='pg_cron' AND d.classid='pg_proc'::regclass
     AND d.objid=to_regprocedure('cron.alter_job(bigint,text,text,text,text,boolean)') AND d.deptype='e') THEN
  RAISE EXCEPTION 'accounting_cron_requires_actual_pg17_pg_cron';END IF;
 IF current_setting('cron.timezone',true) IS NULL
  OR current_setting('cron.timezone',true) NOT IN('GMT','UTC','Etc/UTC','America/Chicago','America/Los_Angeles') THEN
  RAISE EXCEPTION 'accounting_cron_timezone_requires_qualification';END IF;
END $cron_source_guard$;

-- The serializable snapshot and actual extension-owned update protect this
-- owned-job preimage without table-wide exclusion of unrelated cron writers.
DO $change_existing_job$
DECLARE
 job cron.job%ROWTYPE;
 before_row jsonb;
 after_row jsonb;
 expected_command text:=$close$
  SET statement_timeout = '2400s';
  select case
           when pg_try_advisory_lock(hashtext('union-weekly-rakeback-close'))
             then (select set_config('statement_timeout','2400s',true) is not null
                      and public.fn_union_settlement_cascade_due() IS NOT NULL)::text
           else 'skipped: previous run still in progress'
         end;
  $close$;
 final_command text:='SET statement_timeout=''2400s''; SELECT public.fn_union_settlement_cascade_due();';
 definition text;
BEGIN
 IF (SELECT count(*) FROM cron.job WHERE jobname='union-weekly-rakeback-close')<>1
  OR EXISTS(SELECT 1 FROM cron.job WHERE jobname='union-weekly-rakeback-recompute') THEN
  RAISE EXCEPTION 'accounting_cron_single_authority_preimage_changed';END IF;
 SELECT * INTO job FROM cron.job WHERE jobname='union-weekly-rakeback-close';
 IF job.active IS DISTINCT FROM true OR job.schedule IS DISTINCT FROM '5,35 * * * *'
  OR job.command IS DISTINCT FROM expected_command OR job.database IS DISTINCT FROM current_database()
  OR job.username IS NULL OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname=job.username) THEN
  RAISE EXCEPTION 'accounting_cron_schedule_preimage_changed';END IF;
 SELECT pg_get_functiondef('public.fn_process_weekly_accounting_scope(uuid,uuid)'::regprocedure) INTO definition;
 IF md5(pg_get_functiondef('public.fn_process_weekly_accounting(uuid)'::regprocedure)) IS DISTINCT FROM '5aec6700bf043463e9db2933ca63bca1'
  OR position('AND v_now>=public.fn_union_accounting_run_at(public.fn_union_week_start(w.first_week+interval ''8 days'')) GROUP BY w.club_id' IN definition)=0
  OR position('-- A source writer may have held this period lock across the deadline,' IN definition)=0
  OR position('AND q.status=''complete'' AND q.result->>''success''=''true'' AND q.result->>''accounting_version''=''3''' IN definition)=0 THEN
  RAISE EXCEPTION 'accounting_cron_timing_predecessor_missing';END IF;
 before_row:=to_jsonb(job);
 -- Return the captured direct JSON result again after the sealed intermediate
 -- guard. IS NOT NULL would turn a refused result into a true query value.
 -- The coordinator retains its own transaction advisory lock.
 PERFORM cron.alter_job(job_id:=job.jobid,schedule:='0,30 * * * *',command:=final_command);
 SELECT to_jsonb(j) INTO after_row FROM cron.job j WHERE j.jobid=job.jobid;
 IF after_row IS DISTINCT FROM jsonb_set(jsonb_set(before_row,'{schedule}',to_jsonb('0,30 * * * *'::text)),
    '{command}',to_jsonb(final_command))
  OR (SELECT count(*) FROM cron.job WHERE jobname='union-weekly-rakeback-close')<>1 THEN
  RAISE EXCEPTION 'accounting_cron_changed_more_than_schedule';END IF;
END $change_existing_job$;

-- Component 20260914163500_messenger_readers_preserve_private_invoices_and_weekly_summaries.sql
-- SOURCE CANDIDATE ONLY. UNRUN / UNAPPLIED. Club Arena owner integrates this
-- outside the sealed accounting and monitoring candidates, after source review.
-- Existing participants and genuine discussion messages are not changed.

SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='60s';

DO $guard$
DECLARE r record; expected text; actual text; target_proc_oid regprocedure;
BEGIN
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'messenger_privacy_owner_required'; END IF;
 IF md5(pg_get_functiondef('public.fn_caller_is_engine()'::regprocedure))
    IS DISTINCT FROM 'd9a70f1d932538025e656bfe2b4d091d'
 THEN RAISE EXCEPTION 'messenger_engine_authority_changed'; END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname IN('anon','authenticated')
    AND (rolsuper OR rolbypassrls OR pg_has_role(rolname,'service_role','USAGE')))
 THEN RAISE EXCEPTION 'messenger_client_role_bypasses_privacy'; END IF;
 FOR r IN SELECT unnest(ARRAY['social_messages','social_conversations','settlement_invoices',
          'accounting_invoice_deliveries','notifications']) AS name LOOP
   IF NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
      WHERE n.nspname='public' AND c.relname=r.name AND c.relkind='r'
      AND c.relowner='postgres'::regrole AND c.relrowsecurity AND NOT c.relforcerowsecurity)
   THEN RAISE EXCEPTION 'messenger_table_authority_changed: %',r.name; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
    WHERE n.nspname='public' AND p.proname IN('fn_messenger_invoice_visible_to',
      'fn_messenger_message_visible_to','fn_messenger_notification_visible_to',
      'fn_messenger_safe_accounting_preview','fn_messenger_private_message_page',
      'fn_messenger_private_search_messages','fn_messenger_private_accounting_threads',
      'fn_messenger_private_weekly_summary'))
 THEN RAISE EXCEPTION 'messenger_privacy_contract_already_exists'; END IF;
 -- The weekly wrapper requires the final v3 canonical reader, not the older
 -- union-only reader. Hash is prosrc extracted from the reviewed 14:22:56
 -- weekly-v3 component; it is source custody, not an installed readback claim.
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('public.fn_club_weekly_accounting_summary(uuid)')
    AND p.proowner='postgres'::regrole AND p.prosecdef AND p.provolatile='s' AND NOT p.proretset
    AND p.prorettype='jsonb'::regtype AND p.proconfig=ARRAY['search_path=public']
    AND md5(p.prosrc)='045a427e9ad0a0d9eddb08dca2a4bbb4')
 THEN RAISE EXCEPTION 'messenger_weekly_v3_summary_source_changed'; END IF;
 expected:=$party$
 SELECT DISTINCT p.id FROM public.profiles p WHERE p.id IN (
  SELECT p_id WHERE p_kind IN('agent','player')
  UNION SELECT c.owner_id FROM public.clubs c WHERE p_kind='club' AND c.id=p_id
  UNION SELECT m.user_id FROM public.club_members m WHERE p_kind='club' AND m.club_id=p_id
   AND m.role IN('owner','co_owner','admin') AND COALESCE(m.status,'active') IN('active','approved')
  UNION SELECT u.owner_id FROM public.unions u WHERE p_kind='union' AND u.id=p_id
  UNION SELECT a.user_id FROM public.union_admins a WHERE p_kind='union' AND a.union_id=p_id
   AND public.fn_is_union_overseer(p_id,a.user_id)
 );
$party$;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('public.fn_accounting_party_users(text,uuid)')
    AND p.proowner='postgres'::regrole AND p.prosecdef AND p.provolatile='s' AND p.proretset
    AND p.prorettype='uuid'::regtype AND p.proargnames=ARRAY['p_kind','p_id','user_id']
    AND p.proargmodes=ARRAY['i','i','t']::"char"[]
    AND p.proconfig=ARRAY['search_path=public'] AND p.prosrc=expected)
 OR has_function_privilege('anon','public.fn_accounting_party_users(text,uuid)','EXECUTE')
 OR has_function_privilege('authenticated','public.fn_accounting_party_users(text,uuid)','EXECUTE')
 OR NOT has_function_privilege('service_role','public.fn_accounting_party_users(text,uuid)','EXECUTE')
 OR NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid='public.settlement_periods'::regclass
    AND c.relowner='postgres'::regrole AND c.relkind='r' AND c.relrowsecurity AND NOT c.relforcerowsecurity)
 THEN RAISE EXCEPTION 'messenger_weekly_recipient_authority_changed'; END IF;
 -- Exact function bodies below are the reviewed 12:44 and 13:06 migration
 -- sources. Compare before rewriting; preserve owner, ACL and all attributes.
 FOR r IN SELECT * FROM (VALUES
 ('public.fn_messenger_message_page(uuid,uuid,timestamptz,uuid,integer)', $page$
BEGIN
 IF p_limit IS NULL OR p_limit<1 OR p_limit>200 OR (p_before_id IS NOT NULL AND p_before IS NULL) THEN
   RAISE EXCEPTION 'invalid_message_page' USING ERRCODE='22023'; END IF;
 IF (NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR auth.uid()<>p_user_id))
 OR NOT EXISTS(SELECT 1 FROM public.social_conversation_participants p WHERE p.user_id=p_user_id AND p.conversation_id=p_conversation_id) THEN
   RAISE EXCEPTION 'message_page_not_authorised' USING ERRCODE='42501'; END IF;
 RETURN QUERY SELECT m.id,m.conversation_id,m.sender_id,m.content,
   CASE WHEN m.message_type='invoice' AND i.id IS NULL THEN 'text' ELSE m.message_type END,
   COALESCE(m.media_metadata,'{}')||CASE WHEN i.id IS NULL THEN jsonb_build_object('accounting_verified',false)
     ELSE jsonb_build_object('accounting_verified',true,'invoice_id',i.id,'issued_status',m.media_metadata->'status',
       'status',i.status,'chips_transferred',i.chips_transferred) END,
   m.created_at,m.updated_at,m.is_deleted,m.is_edited,
   jsonb_build_object('id',pr.id,'username',pr.username,'avatar_url',pr.avatar_url,'is_vip',pr.is_vip)
 FROM public.social_messages m
 LEFT JOIN public.accounting_invoice_deliveries d ON d.message_id=m.id
 LEFT JOIN public.settlement_invoices i ON i.id=d.invoice_id
 LEFT JOIN public.profiles pr ON pr.id=m.sender_id
 WHERE m.conversation_id=p_conversation_id AND COALESCE(m.is_deleted,false)=false
   AND COALESCE(d.delivery_mode,'immediate')<>'weekly_detail'
   AND (p_before IS NULL OR m.created_at<p_before OR (p_before_id IS NOT NULL AND m.created_at=p_before AND m.id<p_before_id))
 ORDER BY m.created_at DESC,m.id DESC LIMIT p_limit;
END $page$),
 ('public.fn_messenger_accounting_threads(uuid,uuid[])', $threads$
BEGIN
 IF p_user_id IS NULL OR p_conversation_ids IS NULL OR cardinality(p_conversation_ids)>200 THEN
  RAISE EXCEPTION 'invalid_accounting_thread_request' USING ERRCODE='22023'; END IF;
 IF NOT public.fn_caller_is_engine() AND (auth.uid() IS NULL OR auth.uid()<>p_user_id) THEN
  RAISE EXCEPTION 'accounting_threads_not_authorised' USING ERRCODE='42501'; END IF;
 RETURN QUERY SELECT c.conversation_id,
  EXISTS(SELECT 1 FROM public.accounting_invoice_deliveries d JOIN public.social_messages m ON m.id=d.message_id
    WHERE m.conversation_id=c.conversation_id AND d.recipient_id=p_user_id AND d.delivery_mode='immediate' AND COALESCE(m.is_deleted,false)=false),
  visible.content,visible.created_at
 FROM public.accounting_conversations c
 JOIN public.social_conversation_participants p ON p.conversation_id=c.conversation_id AND p.user_id=p_user_id
 LEFT JOIN LATERAL(SELECT m.content,m.created_at FROM public.social_messages m
   LEFT JOIN public.accounting_invoice_deliveries d ON d.message_id=m.id
   WHERE m.conversation_id=c.conversation_id AND COALESCE(m.is_deleted,false)=false
     AND COALESCE(d.delivery_mode,'immediate')<>'weekly_detail'
   ORDER BY m.created_at DESC,m.id DESC LIMIT 1) visible ON true
 WHERE c.conversation_id=ANY(p_conversation_ids) AND (c.sender_id=p_user_id OR c.recipient_id=p_user_id);
END $threads$)
 ) AS originals(signature,body) LOOP
   target_proc_oid:=to_regprocedure(r.signature);
   SELECT p.prosrc INTO actual FROM pg_proc p WHERE p.oid=target_proc_oid;
   IF actual IS DISTINCT FROM r.body OR NOT EXISTS(SELECT 1 FROM pg_proc p
       WHERE p.oid=target_proc_oid AND p.proowner='postgres'::regrole AND p.prosecdef
       AND p.provolatile='s' AND p.proretset AND p.proconfig=ARRAY['search_path=public'])
   THEN RAISE EXCEPTION 'messenger_reader_source_changed: %',r.signature; END IF;
 END LOOP;
 IF md5(pg_get_functiondef('public.fn_messenger_search_messages(uuid,uuid[],text,integer)'::regprocedure))
    IS DISTINCT FROM '8a435bb2242375fd1e00055cba8f50e0'
 THEN RAISE EXCEPTION 'messenger_search_source_changed'; END IF;
 FOR r IN SELECT unnest(ARRAY['public.fn_messenger_message_page(uuid,uuid,timestamptz,uuid,integer)',
    'public.fn_messenger_accounting_threads(uuid,uuid[])','public.fn_messenger_search_messages(uuid,uuid[],text,integer)']) AS signature LOOP
   IF has_function_privilege('anon',r.signature,'EXECUTE')
      OR NOT has_function_privilege('authenticated',r.signature,'EXECUTE')
      OR NOT has_function_privilege('service_role',r.signature,'EXECUTE')
   THEN RAISE EXCEPTION 'messenger_reader_acl_changed: %',r.signature; END IF;
 END LOOP;
END $guard$;

-- One STABLE statement snapshot covers actual actor, exact recipient, recorded
-- period and canonical report. This wrapper does no accounting and writes none.
CREATE FUNCTION public.fn_messenger_private_weekly_summary(p_user_id uuid,p_club_id uuid,p_period_id uuid)
RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $function$
DECLARE period public.settlement_periods%ROWTYPE; report jsonb; summary jsonb;
BEGIN
 IF p_user_id IS NULL OR p_club_id IS NULL OR p_period_id IS NULL
    OR (NOT public.fn_caller_is_engine() AND auth.uid() IS DISTINCT FROM p_user_id)
 THEN RAISE EXCEPTION 'weekly_summary_not_authorised' USING ERRCODE='42501'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.fn_accounting_party_users('club',p_club_id) u WHERE u.user_id=p_user_id)
    OR NOT EXISTS(SELECT 1 FROM public.club_members m WHERE m.club_id=p_club_id AND m.user_id=p_user_id
      AND m.is_active AND m.membership_lifecycle_status='active' AND m.status IN('active','approved'))
 THEN RAISE EXCEPTION 'weekly_summary_not_authorised' USING ERRCODE='42501'; END IF;
 SELECT * INTO period FROM public.settlement_periods WHERE id=p_period_id AND club_id=p_club_id;
 IF NOT FOUND OR period.start_at IS NULL OR period.end_at IS NULL
    OR NOT isfinite(period.start_at) OR NOT isfinite(period.end_at)
    OR period.start_at>=period.end_at OR period.end_at>now()
 THEN RAISE EXCEPTION 'weekly_summary_period_unavailable' USING ERRCODE='22023'; END IF;
 IF EXISTS(SELECT 1 FROM public.settlement_periods other WHERE other.club_id=period.club_id
    AND other.end_at=period.end_at AND other.id<>period.id)
 THEN RAISE EXCEPTION 'weekly_summary_ambiguous_recorded_books' USING ERRCODE='22023'; END IF;
 report:=public.fn_club_weekly_accounting_summary(period.id);
 IF jsonb_typeof(report) IS DISTINCT FROM 'object'
    OR report->'accounting_version' IS DISTINCT FROM '3'::jsonb
    OR report->>'period_id' IS DISTINCT FROM period.id::text
    OR report->>'club_id' IS DISTINCT FROM period.club_id::text
    OR NOT (report ? 'union_id') OR report->>'union_id' IS DISTINCT FROM period.union_id::text
    OR report->>'scope_kind' IS DISTINCT FROM (CASE WHEN period.union_id IS NULL THEN 'club' ELSE 'union' END)
    OR report->>'scope_id' IS DISTINCT FROM COALESCE(period.union_id,period.club_id)::text
    OR report->>'currency' IS DISTINCT FROM 'CHIPS'
    OR COALESCE(report->>'status','') NOT IN('needs_reconciliation','complete')
    OR NOT COALESCE(pg_input_is_valid(report->>'period_start','timestamptz'),false)
    OR NOT COALESCE(pg_input_is_valid(report->>'period_end','timestamptz'),false)
 THEN RAISE EXCEPTION 'weekly_summary_contract_unavailable' USING ERRCODE='23514'; END IF;
 IF (report->>'period_start')::timestamptz IS DISTINCT FROM period.start_at
    OR (report->>'period_end')::timestamptz IS DISTINCT FROM period.end_at
    OR (report->>'status'='complete' AND report->'ready_to_issue' IS DISTINCT FROM 'true'::jsonb)
 THEN RAISE EXCEPTION 'weekly_summary_contract_unavailable' USING ERRCODE='23514'; END IF;
 -- Only aggregate scalar fields cross the Messenger boundary. Bank/source IDs,
 -- source fingerprints, recipient lists and per-tournament diagnostics stay in
 -- the canonical administrative report, never in this recipient preview.
 SELECT COALESCE(jsonb_object_agg(e.key,e.value),'{}'::jsonb) INTO summary
 FROM jsonb_each(report) e WHERE e.key=ANY(ARRAY[
  'accounting_version','scope_kind','scope_id','period_id','club_id','union_id','period_start','period_end','currency',
  'rake_earned','union_rake_earned','private_rake_earned','private_rake_banked','private_rake_burned','rake_received','expected_union_receipt',
  'total_rake_funding','paid_super_agents','paid_agents','paid_sub_agents','paid_players','paid_unclassified',
  'total_paid_by_club','retained_by_club','downstream_redistributed','downstream_paid_super_agents',
  'downstream_paid_agents','downstream_paid_sub_agents','downstream_paid_players','transfer_count','source_count',
  'unclassified_role_count','missing_period_count','receipt_issue_count','source_issue_count','certified_stage_count',
  'ready_to_issue','status','run_status','basis_source','note']) AND jsonb_typeof(e.value) NOT IN('object','array');
 RETURN jsonb_build_object('contract_version',1,'user_id',p_user_id,'club_id',p_club_id,'period_id',p_period_id,'summary',summary);
END $function$;
REVOKE ALL ON FUNCTION public.fn_messenger_private_weekly_summary(uuid,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_messenger_private_weekly_summary(uuid,uuid,uuid) TO authenticated,service_role;

-- This is an additional restriction, never a grant of invoice access. Existing
-- own-delivery / club-admin / union-overseer SELECT policies remain underneath.
CREATE FUNCTION public.fn_messenger_invoice_visible_to(p_invoice_id uuid,p_user_id uuid)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $function$
BEGIN
 IF p_user_id IS NULL OR (NOT public.fn_caller_is_engine() AND auth.uid() IS DISTINCT FROM p_user_id)
 THEN RETURN false; END IF;
 RETURN EXISTS(SELECT 1 FROM public.settlement_invoices i WHERE i.id=p_invoice_id
   AND (NOT (i.from_entity_type='club' AND i.to_entity_type IN('agent','player')
       AND i.source_ledger_id IS NOT NULL AND COALESCE(i.breakdown->>'category','') IN('rakeback','commission'))
     OR EXISTS(SELECT 1 FROM public.accounting_invoice_deliveries d
       WHERE d.invoice_id=i.id AND d.recipient_id=p_user_id AND d.delivery_mode='immediate')));
END $function$;

CREATE FUNCTION public.fn_messenger_message_visible_to(p_message_id uuid,p_user_id uuid)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $function$
BEGIN
 IF p_user_id IS NULL OR (NOT public.fn_caller_is_engine() AND auth.uid() IS DISTINCT FROM p_user_id)
 THEN RETURN false; END IF;
 RETURN EXISTS(SELECT 1 FROM public.social_messages m
   JOIN public.social_conversation_participants p ON p.conversation_id=m.conversation_id AND p.user_id=p_user_id
   LEFT JOIN public.accounting_invoice_deliveries d ON d.message_id=m.id
   WHERE m.id=p_message_id AND NOT COALESCE(m.is_deleted,false)
     AND COALESCE(d.delivery_mode,'immediate')<>'weekly_detail'
     AND (d.invoice_id IS NULL OR public.fn_messenger_invoice_visible_to(d.invoice_id,p_user_id)));
END $function$;

CREATE FUNCTION public.fn_messenger_notification_visible_to(p_notification_id uuid,p_user_id uuid)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $function$
BEGIN
 IF p_user_id IS NULL OR (NOT public.fn_caller_is_engine() AND auth.uid() IS DISTINCT FROM p_user_id)
 THEN RETURN false; END IF;
 RETURN EXISTS(SELECT 1 FROM public.notifications n
   LEFT JOIN public.accounting_invoice_deliveries d ON d.notification_id=n.id
   WHERE n.id=p_notification_id AND n.user_id=p_user_id AND n.type IS DISTINCT FROM 'accounting_invoice_detail'
     AND COALESCE(d.delivery_mode,'immediate')<>'weekly_detail'
     AND (d.invoice_id IS NULL OR public.fn_messenger_invoice_visible_to(d.invoice_id,p_user_id)));
END $function$;

REVOKE ALL ON FUNCTION public.fn_messenger_invoice_visible_to(uuid,uuid),
 public.fn_messenger_message_visible_to(uuid,uuid),public.fn_messenger_notification_visible_to(uuid,uuid)
 FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_messenger_invoice_visible_to(uuid,uuid),
 public.fn_messenger_message_visible_to(uuid,uuid),public.fn_messenger_notification_visible_to(uuid,uuid)
 TO authenticated,service_role;

CREATE POLICY messenger_private_invoice_content ON public.settlement_invoices AS RESTRICTIVE
 FOR SELECT TO authenticated USING(public.fn_messenger_invoice_visible_to(id,(SELECT auth.uid())));
CREATE POLICY messenger_private_message_content ON public.social_messages AS RESTRICTIVE
 FOR SELECT TO authenticated USING(public.fn_messenger_message_visible_to(id,(SELECT auth.uid())));
CREATE POLICY messenger_private_delivery_content ON public.accounting_invoice_deliveries AS RESTRICTIVE
 FOR SELECT TO authenticated USING(delivery_mode='immediate' AND public.fn_messenger_invoice_visible_to(invoice_id,(SELECT auth.uid())));
CREATE POLICY messenger_private_notification_content ON public.notifications AS RESTRICTIVE
 FOR SELECT TO authenticated USING(public.fn_messenger_notification_visible_to(id,(SELECT auth.uid())));
CREATE POLICY messenger_no_anonymous_invoice_content ON public.settlement_invoices AS RESTRICTIVE FOR SELECT TO anon USING(false);
CREATE POLICY messenger_no_anonymous_message_content ON public.social_messages AS RESTRICTIVE FOR SELECT TO anon USING(false);
CREATE POLICY messenger_no_anonymous_delivery_content ON public.accounting_invoice_deliveries AS RESTRICTIVE FOR SELECT TO anon USING(false);
CREATE POLICY messenger_no_anonymous_notification_content ON public.notifications AS RESTRICTIVE FOR SELECT TO anon USING(false);

-- Shared table preview cannot contain recipient-specific invoice text. Readers
-- above compute each participant's permitted preview from actual messages.
CREATE FUNCTION public.fn_messenger_safe_accounting_preview() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $function$
BEGIN
 IF EXISTS(SELECT 1 FROM public.accounting_conversations c WHERE c.conversation_id=NEW.id)
 THEN NEW.last_message_preview:='Accounting Conversation'; END IF;
 RETURN NEW;
END $function$;
REVOKE ALL ON FUNCTION public.fn_messenger_safe_accounting_preview() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER messenger_safe_accounting_preview BEFORE INSERT OR UPDATE OF last_message_preview
 ON public.social_conversations FOR EACH ROW EXECUTE FUNCTION public.fn_messenger_safe_accounting_preview();
UPDATE public.social_conversations c SET last_message_preview='Accounting Conversation'
 WHERE EXISTS(SELECT 1 FROM public.accounting_conversations ac WHERE ac.conversation_id=c.id)
   AND c.last_message_preview IS DISTINCT FROM 'Accounting Conversation';

DO $rewrite$
DECLARE signature text; definition text; anchor text:='AND COALESCE(d.delivery_mode,''immediate'')<>''weekly_detail''';
BEGIN
 FOREACH signature IN ARRAY ARRAY['public.fn_messenger_message_page(uuid,uuid,timestamptz,uuid,integer)',
   'public.fn_messenger_search_messages(uuid,uuid[],text,integer)','public.fn_messenger_accounting_threads(uuid,uuid[])'] LOOP
   definition:=pg_get_functiondef(signature::regprocedure);
   IF (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1
   THEN RAISE EXCEPTION 'messenger_private_filter_anchor_changed: %',signature; END IF;
   EXECUTE replace(definition,anchor,anchor||E'\n     AND public.fn_messenger_message_visible_to(m.id,p_user_id)');
 END LOOP;
END $rewrite$;

-- New entry names make old database installations fail closed at the caller.
-- Old entry names remain protected for direct authenticated RPC clients.
CREATE FUNCTION public.fn_messenger_private_message_page(p_user_id uuid,p_conversation_id uuid,
 p_before timestamptz DEFAULT NULL,p_before_id uuid DEFAULT NULL,p_limit integer DEFAULT 50)
RETURNS TABLE(id uuid,conversation_id uuid,sender_id uuid,content text,message_type text,media_metadata jsonb,
 created_at timestamptz,updated_at timestamptz,is_deleted boolean,is_edited boolean,profiles jsonb)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $function$
 SELECT * FROM public.fn_messenger_message_page(p_user_id,p_conversation_id,p_before,p_before_id,p_limit);
$function$;
CREATE FUNCTION public.fn_messenger_private_search_messages(p_user_id uuid,p_conversation_ids uuid[],p_query text,p_limit integer DEFAULT 50)
RETURNS TABLE(id uuid,conversation_id uuid,sender_id uuid,content text,created_at timestamptz,message_type text,media_metadata jsonb)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $function$
 SELECT * FROM public.fn_messenger_search_messages(p_user_id,p_conversation_ids,p_query,p_limit);
$function$;
CREATE FUNCTION public.fn_messenger_private_accounting_threads(p_user_id uuid,p_conversation_ids uuid[])
RETURNS TABLE(conversation_id uuid,recipient_visible boolean,last_message_preview text,last_message_at timestamptz)
LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $function$
 SELECT * FROM public.fn_messenger_accounting_threads(p_user_id,p_conversation_ids);
$function$;
REVOKE ALL ON FUNCTION public.fn_messenger_private_message_page(uuid,uuid,timestamptz,uuid,integer),
 public.fn_messenger_private_search_messages(uuid,uuid[],text,integer),public.fn_messenger_private_accounting_threads(uuid,uuid[])
 FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_messenger_private_message_page(uuid,uuid,timestamptz,uuid,integer),
 public.fn_messenger_private_search_messages(uuid,uuid[],text,integer),public.fn_messenger_private_accounting_threads(uuid,uuid[])
 TO authenticated,service_role;

-- Component 20260914164000_push_enrollment_changes_endpoint_ownership_atomically.sql
-- SOURCE CANDIDATE ONLY. UNRUN / UNAPPLIED. Club Arena owns the database.
-- Requires the captured push_subscriptions schema, its existing per-account
-- endpoint/device uniqueness, and service-only enrollment through World Hub.
-- No existing endpoint is retired by installing this file. Conflicting active
-- ownership aborts installation for investigation instead of choosing a user.

SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='60s';
DO $guard$
BEGIN
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'push_ownership_owner_required'; END IF;
 IF to_regprocedure('public.fn_change_push_subscription_ownership(uuid,jsonb,boolean)') IS NOT NULL
    OR to_regclass('public.push_subscriptions_one_active_endpoint_uidx') IS NOT NULL
 THEN RAISE EXCEPTION 'push_ownership_contract_already_exists'; END IF;
 IF md5(pg_get_functiondef('public.fn_caller_is_engine()'::regprocedure))
    IS DISTINCT FROM 'd9a70f1d932538025e656bfe2b4d091d'
 THEN RAISE EXCEPTION 'push_ownership_engine_authority_changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='public.push_subscriptions'::regclass
    AND relowner='postgres'::regrole AND relrowsecurity AND NOT relforcerowsecurity)
    OR NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.push_subscriptions'::regclass
      AND conname='push_subscriptions_user_id_endpoint_key' AND contype='u'
      AND pg_get_constraintdef(oid)='UNIQUE (user_id, endpoint)')
    OR pg_get_indexdef(to_regclass('public.push_subscriptions_one_active_per_device_uidx')) IS DISTINCT FROM
      'CREATE UNIQUE INDEX push_subscriptions_one_active_per_device_uidx ON public.push_subscriptions USING btree (user_id, device_id) WHERE (is_active AND (device_id IS NOT NULL))'
    OR NOT EXISTS(SELECT 1 FROM pg_index WHERE indexrelid=to_regclass('public.push_subscriptions_one_active_per_device_uidx')
      AND indisunique AND indisvalid AND indisready)
 THEN RAISE EXCEPTION 'push_ownership_schema_changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass('public.notification_preferences')
    AND relowner='postgres'::regrole AND relkind='r')
    OR EXISTS(SELECT 1 FROM (VALUES('user_id','uuid'::regtype),('push_enabled','boolean'::regtype),
        ('browser_push','boolean'::regtype),('updated_at','timestamptz'::regtype)) expected(name,type)
      WHERE NOT EXISTS(SELECT 1 FROM pg_attribute a WHERE a.attrelid=to_regclass('public.notification_preferences')
        AND a.attname=expected.name AND a.atttypid=expected.type AND NOT a.attisdropped))
 THEN RAISE EXCEPTION 'push_ownership_preference_contract_changed'; END IF;
 IF EXISTS(SELECT 1 FROM pg_policy p WHERE p.polrelid='public.push_subscriptions'::regclass
     AND p.polcmd IN('a','w','*') AND p.polpermissive
     AND EXISTS(SELECT 1 FROM pg_roles client CROSS JOIN LATERAL unnest(p.polroles) granted(role_id)
       WHERE client.rolname IN('anon','authenticated') AND
         CASE WHEN granted.role_id=0 THEN true ELSE pg_has_role(client.oid,granted.role_id,'USAGE') END))
 THEN RAISE EXCEPTION 'push_ownership_client_writer_present'; END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname IN('anon','authenticated')
    AND (rolsuper OR rolbypassrls OR pg_has_role(rolname,'service_role','USAGE')))
 THEN RAISE EXCEPTION 'push_ownership_client_role_bypass'; END IF;
 IF EXISTS(SELECT 1 FROM public.push_subscriptions WHERE is_active GROUP BY endpoint HAVING count(*)>1)
 THEN RAISE EXCEPTION 'push_ownership_existing_active_conflict'; END IF;
END $guard$;

-- This enforces uniqueness even against a trusted writer that does not take
-- the enrollment lock. The existing per-user/device index remains in force.
CREATE UNIQUE INDEX push_subscriptions_one_active_endpoint_uidx
 ON public.push_subscriptions(endpoint) WHERE is_active;

CREATE FUNCTION public.fn_change_push_subscription_ownership(p_user_id uuid,p_subscription jsonb,p_enabled boolean)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $function$
DECLARE endpoint_value text:=p_subscription->>'endpoint';
 transport_value text:=p_subscription->>'transport'; platform_value text:=p_subscription->>'platform';
 auth_value text:=p_subscription->>'auth'; key_value text:=p_subscription->>'p256dh';
 device_value text:=p_subscription->>'device_id'; replaces_value text:=p_subscription->>'replaces_endpoint';
 displaced uuid[]:='{}'; incumbent public.push_subscriptions%ROWTYPE;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_user_id IS NULL OR p_enabled IS NULL OR jsonb_typeof(p_subscription) IS DISTINCT FROM 'object'
    OR endpoint_value IS NULL OR length(endpoint_value)<1 OR length(endpoint_value)>4096
 THEN RAISE EXCEPTION 'invalid_push_subscription' USING ERRCODE='22023'; END IF;
 -- Enrollment is rare and bounded. One transaction lock also orders device
 -- replacement and logout, avoiding reversed endpoint/device lock ordering.
 PERFORM pg_advisory_xact_lock(hashtextextended('push_subscription_ownership:v1',0));
 IF p_enabled THEN
   IF transport_value IS NULL OR transport_value NOT IN('webpush','fcm')
      OR (platform_value IS NOT NULL AND platform_value NOT IN('web','ios','android'))
      OR (transport_value='webpush' AND (COALESCE(auth_value,'')='' OR COALESCE(key_value,'')=''))
      OR (device_value IS NOT NULL AND device_value !~ '^[A-Za-z0-9-]{8,64}$')
   THEN RAISE EXCEPTION 'invalid_push_subscription' USING ERRCODE='22023'; END IF;
   -- The caller already validates endpoint hosts, native token shape and key
   -- lengths. This service-only transaction repeats ownership proof while
   -- holding the same lock that protects retirement and replacement.
   FOR incumbent IN SELECT * FROM public.push_subscriptions
     WHERE endpoint=endpoint_value AND is_active AND user_id<>p_user_id ORDER BY id FOR UPDATE LOOP
     IF incumbent.transport IS DISTINCT FROM transport_value OR
        (transport_value='webpush' AND incumbent.auth IS DISTINCT FROM auth_value)
     THEN RAISE EXCEPTION 'push_subscription_possession_mismatch' USING ERRCODE='23514'; END IF;
     displaced:=array_append(displaced,incumbent.user_id);
   END LOOP;
   UPDATE public.push_subscriptions SET is_active=false,last_failure_reason='reassigned_to_other_user',updated_at=now()
     WHERE endpoint=endpoint_value AND is_active AND user_id<>p_user_id;
   IF device_value IS NOT NULL THEN
     UPDATE public.push_subscriptions SET is_active=false,last_failure_reason='superseded_same_device',updated_at=now()
       WHERE user_id=p_user_id AND device_id=device_value AND is_active AND endpoint<>endpoint_value;
   END IF;
   IF replaces_value IS NOT NULL AND replaces_value<>endpoint_value THEN
     UPDATE public.push_subscriptions SET is_active=false,last_failure_reason='superseded',updated_at=now()
       WHERE user_id=p_user_id AND endpoint=replaces_value AND is_active;
   END IF;
   INSERT INTO public.push_subscriptions(user_id,endpoint,p256dh,auth,transport,platform,user_agent,device_label,
     device_id,is_active,failure_count,last_failure_reason,updated_at)
   VALUES(p_user_id,endpoint_value,key_value,auth_value,transport_value,platform_value,
     left(p_subscription->>'user_agent',500),left(p_subscription->>'device_label',120),device_value,true,0,NULL,now())
   ON CONFLICT(user_id,endpoint) DO UPDATE SET p256dh=EXCLUDED.p256dh,auth=EXCLUDED.auth,transport=EXCLUDED.transport,
     platform=EXCLUDED.platform,user_agent=EXCLUDED.user_agent,device_label=EXCLUDED.device_label,
     device_id=EXCLUDED.device_id,is_active=true,failure_count=0,last_failure_reason=NULL,updated_at=EXCLUDED.updated_at;
   INSERT INTO public.notification_preferences(user_id,push_enabled,browser_push,updated_at)
     VALUES(p_user_id,true,true,now()) ON CONFLICT(user_id) DO UPDATE
     SET push_enabled=true,browser_push=true,updated_at=EXCLUDED.updated_at;
 ELSE
   UPDATE public.push_subscriptions SET is_active=false,updated_at=now()
     WHERE user_id=p_user_id AND endpoint=endpoint_value AND is_active;
   IF NOT EXISTS(SELECT 1 FROM public.push_subscriptions WHERE user_id=p_user_id AND is_active) THEN
     INSERT INTO public.notification_preferences(user_id,push_enabled,updated_at) VALUES(p_user_id,false,now())
       ON CONFLICT(user_id) DO UPDATE SET push_enabled=false,updated_at=EXCLUDED.updated_at;
   END IF;
 END IF;
 RETURN jsonb_build_object('schema_version',1,'success',true,'user_id',p_user_id,
   'endpoint',endpoint_value,'enabled',p_enabled,'displaced_user_ids',to_jsonb(displaced));
END $function$;
REVOKE ALL ON FUNCTION public.fn_change_push_subscription_ownership(uuid,jsonb,boolean) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_change_push_subscription_ownership(uuid,jsonb,boolean) TO service_role;

-- Component 20260914164500_push_rotation_preserves_current_subscription_ownership.sql
-- SOURCE CANDIDATE ONLY: UNRUN / UNAPPLIED. Requires component 164000.
-- Authenticated WH requests supply a verified actor; anonymous rotation refuses.
-- This is row-version CAS, NOT installation/account epoch or display proof.

SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='60s';
DO $guard$
BEGIN
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'push_rotation_owner_required'; END IF;
 IF to_regprocedure('public.fn_rotate_push_subscription(uuid,jsonb,jsonb)') IS NOT NULL
    OR to_regprocedure('public.fn_push_subscription_rotation_revision()') IS NOT NULL
    OR EXISTS(SELECT 1 FROM pg_attribute WHERE attrelid='public.push_subscriptions'::regclass
      AND attname='rotation_revision' AND NOT attisdropped)
    OR EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.push_subscriptions'::regclass
      AND tgname='push_subscription_rotation_revision')
 THEN RAISE EXCEPTION 'push_rotation_contract_already_exists'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_change_push_subscription_ownership(uuid,jsonb,boolean)')
    AND proowner='postgres'::regrole AND prosecdef AND prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql')
    AND prorettype='jsonb'::regtype AND proconfig=ARRAY['search_path=public']::text[]
    AND md5(prosrc)='2f40ec68f6cbdd2288c5dd2d313ca358')
    OR md5(pg_get_functiondef('public.fn_caller_is_engine()'::regprocedure))
       IS DISTINCT FROM 'd9a70f1d932538025e656bfe2b4d091d'
 THEN RAISE EXCEPTION 'push_rotation_predecessor_changed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='public.push_subscriptions'::regclass
    AND relowner='postgres'::regrole AND relkind='r' AND relrowsecurity AND NOT relforcerowsecurity)
    OR pg_get_indexdef(to_regclass('public.push_subscriptions_one_active_endpoint_uidx')) IS DISTINCT FROM
       'CREATE UNIQUE INDEX push_subscriptions_one_active_endpoint_uidx ON public.push_subscriptions USING btree (endpoint) WHERE is_active'
    OR pg_get_indexdef(to_regclass('public.push_subscriptions_one_active_per_device_uidx')) IS DISTINCT FROM
       'CREATE UNIQUE INDEX push_subscriptions_one_active_per_device_uidx ON public.push_subscriptions USING btree (user_id, device_id) WHERE (is_active AND (device_id IS NOT NULL))'
    OR EXISTS(SELECT 1 FROM (VALUES('push_subscriptions_one_active_endpoint_uidx'),
       ('push_subscriptions_one_active_per_device_uidx')) expected(name)
       WHERE NOT EXISTS(SELECT 1 FROM pg_index WHERE indexrelid=to_regclass('public.'||expected.name)
         AND indisunique AND indisvalid AND indisready))
 THEN RAISE EXCEPTION 'push_rotation_schema_changed'; END IF;
 IF EXISTS(SELECT 1 FROM pg_roles WHERE rolname IN('anon','authenticated')
    AND (rolsuper OR rolbypassrls OR pg_has_role(rolname,'service_role','USAGE')))
    OR EXISTS(SELECT 1 FROM pg_policy p WHERE p.polrelid='public.push_subscriptions'::regclass
      AND p.polcmd IN('a','w','*') AND p.polpermissive
      AND EXISTS(SELECT 1 FROM pg_roles client CROSS JOIN LATERAL unnest(p.polroles) granted(role_id)
        WHERE client.rolname IN('anon','authenticated') AND
          CASE WHEN granted.role_id=0 THEN true ELSE pg_has_role(client.oid,granted.role_id,'USAGE') END))
    OR has_function_privilege('anon','public.fn_change_push_subscription_ownership(uuid,jsonb,boolean)','EXECUTE')
    OR has_function_privilege('authenticated','public.fn_change_push_subscription_ownership(uuid,jsonb,boolean)','EXECUTE')
    OR NOT has_function_privilege('service_role','public.fn_change_push_subscription_ownership(uuid,jsonb,boolean)','EXECUTE')
 THEN RAISE EXCEPTION 'push_rotation_authority_changed'; END IF;
END $guard$;

-- Default installation does not certify historical ownership. INSERT resets to
-- 1 for a new row ID; every UPDATE increments, including an A->B->A enrollment
-- or telemetry. A caller cannot supply a reset. The bigint overflow aborts the
-- whole statement/transaction; it never wraps. These are not global epochs.
ALTER TABLE public.push_subscriptions ADD COLUMN rotation_revision bigint NOT NULL DEFAULT 1
 CHECK(rotation_revision>0);
CREATE FUNCTION public.fn_push_subscription_rotation_revision()
RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $function$
BEGIN
 IF TG_OP='INSERT' THEN NEW.rotation_revision:=1;
 ELSE NEW.rotation_revision:=OLD.rotation_revision+1;
 END IF;
 RETURN NEW;
END $function$;
REVOKE ALL ON FUNCTION public.fn_push_subscription_rotation_revision() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER push_subscription_rotation_revision BEFORE INSERT OR UPDATE ON public.push_subscriptions
 FOR EACH ROW EXECUTE FUNCTION public.fn_push_subscription_rotation_revision();

CREATE FUNCTION public.fn_rotate_push_subscription(p_user_id uuid,p_expected jsonb,p_replacement jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $function$
DECLARE source public.push_subscriptions%ROWTYPE; target public.push_subscriptions%ROWTYPE;
 old_endpoint text:=p_expected->>'endpoint'; new_endpoint text:=p_replacement->>'endpoint';
 revision text:=p_expected->>'rotation_revision'; retired_revision text;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_user_id IS NULL OR jsonb_typeof(p_expected) IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_replacement) IS DISTINCT FROM 'object'
    OR jsonb_typeof(p_expected->'rotation_revision') IS DISTINCT FROM 'string'
    OR revision !~ '^[1-9][0-9]{0,18}$'
    OR COALESCE(p_expected->>'id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    OR COALESCE(p_expected->>'device_id','') !~ '^[A-Za-z0-9-]{8,64}$'
    OR p_expected->>'transport' IS DISTINCT FROM 'webpush'
    OR COALESCE(length(old_endpoint),0) NOT BETWEEN 1 AND 4096
    OR COALESCE(length(new_endpoint),0) NOT BETWEEN 1 AND 4096
    OR old_endpoint=new_endpoint
    OR COALESCE(p_expected->>'p256dh','')='' OR COALESCE(p_expected->>'auth','')=''
    OR COALESCE(p_replacement->>'p256dh','')='' OR COALESCE(p_replacement->>'auth','')=''
 THEN RAISE EXCEPTION 'invalid_push_rotation' USING ERRCODE='22023'; END IF;
 -- Same lock/order as enrollment. The verified actor came from WH request
 -- authentication, never from an endpoint-owner lookup or request body.
 PERFORM pg_advisory_xact_lock(hashtextextended('push_subscription_ownership:v1',0));
 SELECT * INTO source FROM public.push_subscriptions WHERE id=(p_expected->>'id')::uuid FOR UPDATE;
 IF NOT FOUND OR NOT source.is_active OR source.user_id IS DISTINCT FROM p_user_id
    OR source.endpoint IS DISTINCT FROM old_endpoint OR source.transport IS DISTINCT FROM 'webpush'
    OR source.rotation_revision::text IS DISTINCT FROM revision
    OR source.p256dh IS DISTINCT FROM (p_expected->>'p256dh')
    OR source.auth IS DISTINCT FROM (p_expected->>'auth')
    OR source.device_id IS DISTINCT FROM (p_expected->>'device_id')
 THEN RAISE EXCEPTION 'push_rotation_conflict' USING ERRCODE='23514'; END IF;
 -- No ownership takeover, resurrection, same-device retirement or preferences
 -- changes belong to rotation. Foreground authenticated enrollment handles
 -- conflicts. Cross-account device collisions are refused, not assigned.
 IF EXISTS(SELECT 1 FROM public.push_subscriptions WHERE endpoint=new_endpoint)
    OR EXISTS(SELECT 1 FROM public.push_subscriptions WHERE device_id=source.device_id AND is_active AND id<>source.id)
 THEN RAISE EXCEPTION 'push_rotation_conflict' USING ERRCODE='23514'; END IF;
 UPDATE public.push_subscriptions SET is_active=false,last_failure_reason='rotated',updated_at=clock_timestamp()
   WHERE id=source.id RETURNING rotation_revision::text INTO retired_revision;
 IF retired_revision IS DISTINCT FROM (source.rotation_revision+1)::text THEN
   RAISE EXCEPTION 'push_rotation_write_unconfirmed' USING ERRCODE='23514';
 END IF;
 INSERT INTO public.push_subscriptions(user_id,endpoint,p256dh,auth,user_agent,device_label,
   device_id,transport,platform,is_active,failure_count,last_failure_reason,updated_at)
 VALUES(source.user_id,new_endpoint,p_replacement->>'p256dh',p_replacement->>'auth',source.user_agent,source.device_label,
   source.device_id,'webpush',source.platform,true,0,NULL,clock_timestamp()) RETURNING * INTO target;
 -- Re-read after triggers: a skipped/changed INSERT must not commit retirement.
 SELECT s.* INTO target FROM public.push_subscriptions s WHERE s.id=target.id;
 IF NOT FOUND OR target.id IS NULL OR target.id=source.id OR NOT target.is_active
    OR target.user_id IS DISTINCT FROM source.user_id OR target.endpoint IS DISTINCT FROM new_endpoint
    OR target.p256dh IS DISTINCT FROM (p_replacement->>'p256dh') OR target.auth IS DISTINCT FROM (p_replacement->>'auth')
    OR target.device_id IS DISTINCT FROM source.device_id OR target.device_label IS DISTINCT FROM source.device_label
    OR target.user_agent IS DISTINCT FROM source.user_agent OR target.platform IS DISTINCT FROM source.platform
    OR target.transport IS DISTINCT FROM 'webpush' OR target.rotation_revision IS DISTINCT FROM 1::bigint
    OR target.failure_count IS DISTINCT FROM 0 OR target.last_failure_reason IS NOT NULL
    OR NOT EXISTS(SELECT 1 FROM public.push_subscriptions s WHERE s.id=source.id AND NOT s.is_active
      AND s.rotation_revision::text=retired_revision AND s.last_failure_reason='rotated')
 THEN RAISE EXCEPTION 'push_rotation_write_unconfirmed' USING ERRCODE='23514'; END IF;
 RETURN jsonb_build_object('schema_version',1,'success',true,'user_id',source.user_id,
   'source_subscription_id',source.id,'source_revision',revision,'retired_revision',retired_revision,
   'subscription_id',target.id,'rotation_revision',target.rotation_revision::text,
   'old_endpoint',old_endpoint,'endpoint',target.endpoint,'device_id',target.device_id,'transport',target.transport);
END $function$;
REVOKE ALL ON FUNCTION public.fn_rotate_push_subscription(uuid,jsonb,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.fn_rotate_push_subscription(uuid,jsonb,jsonb) TO service_role;
DO $postcondition$
BEGIN
 IF has_function_privilege('anon','public.fn_rotate_push_subscription(uuid,jsonb,jsonb)','EXECUTE')
    OR has_function_privilege('authenticated','public.fn_rotate_push_subscription(uuid,jsonb,jsonb)','EXECUTE')
    OR NOT has_function_privilege('service_role','public.fn_rotate_push_subscription(uuid,jsonb,jsonb)','EXECUTE')
    OR EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(COALESCE(p.proacl,acldefault('f',p.proowner))) a
       WHERE p.oid='public.fn_rotate_push_subscription(uuid,jsonb,jsonb)'::regprocedure
       AND (a.grantee NOT IN('postgres'::regrole,'service_role'::regrole) OR a.privilege_type<>'EXECUTE'))
 THEN RAISE EXCEPTION 'push_rotation_rpc_acl_not_service_only'; END IF;
END $postcondition$;

-- Component 20260914164600_credit_request_reviews_share_one_credit_authority.sql
-- SOURCE ONLY. One request decision and the existing credit authority share
-- a transaction. Requires the full weekly bundle, including 150500.

SET LOCAL lock_timeout='3s';
SET LOCAL statement_timeout='30s';
LOCK TABLE public.credit_requests IN ACCESS EXCLUSIVE MODE;
DO $preimage$
DECLARE actual jsonb; role_name text; column_name text;
BEGIN
 IF to_regprocedure('public.fn_guard_credit_request_creation()') IS NOT NULL
 THEN RAISE EXCEPTION 'credit_request_creation_guard_preexists';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid='public.credit_requests'::regclass
  AND c.relkind='r' AND pg_get_userbyid(c.relowner)='postgres' AND c.relrowsecurity AND NOT c.relforcerowsecurity
  AND NOT EXISTS(SELECT 1 FROM pg_inherits i WHERE i.inhrelid=c.oid OR i.inhparent=c.oid))
 THEN RAISE EXCEPTION 'credit_request_table_preimage_changed';END IF;
 SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),
   'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl) ORDER BY a.attnum)
 INTO actual FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
 WHERE a.attrelid='public.credit_requests'::regclass AND a.attnum>0 AND NOT a.attisdropped;
 IF actual IS DISTINCT FROM $columns$[{"acl":null,"name":"id","type":"uuid","default":"gen_random_uuid()","not_null":true},{"acl":null,"name":"requester_id","type":"uuid","default":null,"not_null":true},{"acl":null,"name":"approver_id","type":"uuid","default":null,"not_null":false},{"acl":null,"name":"club_id","type":"uuid","default":null,"not_null":true},{"acl":null,"name":"requested_amount","type":"numeric","default":"0","not_null":true},{"acl":null,"name":"approved_amount","type":"numeric","default":null,"not_null":false},{"acl":null,"name":"reason","type":"text","default":null,"not_null":false},{"acl":null,"name":"status","type":"text","default":"'pending'::text","not_null":true},{"acl":null,"name":"reviewer_notes","type":"text","default":null,"not_null":false},{"acl":null,"name":"created_at","type":"timestamp with time zone","default":"now()","not_null":true},{"acl":null,"name":"reviewed_at","type":"timestamp with time zone","default":null,"not_null":false},{"acl":null,"name":"reviewed_by","type":"uuid","default":null,"not_null":false}]$columns$::jsonb THEN RAISE EXCEPTION 'credit_request_columns_changed';END IF;
 SELECT jsonb_agg(to_jsonb(p) ORDER BY policyname) INTO actual FROM pg_policies p
 WHERE schemaname='public' AND tablename='credit_requests';
 IF actual IS DISTINCT FROM $policies$[{"cmd":"INSERT","qual":null,"roles":["authenticated"],"tablename":"credit_requests","permissive":"PERMISSIVE","policyname":"credit_requests_insert_own","schemaname":"public","with_check":"(requester_id = ( SELECT auth.uid() AS uid))"},{"cmd":"SELECT","qual":"((requester_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1\n   FROM clubs c\n  WHERE ((c.id = credit_requests.club_id) AND (c.owner_id = ( SELECT auth.uid() AS uid))))) OR (EXISTS ( SELECT 1\n   FROM club_members cm\n  WHERE ((cm.club_id = credit_requests.club_id) AND (cm.user_id = ( SELECT auth.uid() AS uid)) AND (cm.role = ANY (ARRAY['owner'::text, 'co_owner'::text, 'admin'::text]))))))","roles":["authenticated"],"tablename":"credit_requests","permissive":"PERMISSIVE","policyname":"credit_requests_select","schemaname":"public","with_check":null},{"cmd":"UPDATE","qual":"((EXISTS ( SELECT 1\n   FROM clubs c\n  WHERE ((c.id = credit_requests.club_id) AND (c.owner_id = ( SELECT auth.uid() AS uid))))) OR (EXISTS ( SELECT 1\n   FROM club_members cm\n  WHERE ((cm.club_id = credit_requests.club_id) AND (cm.user_id = ( SELECT auth.uid() AS uid)) AND (cm.role = ANY (ARRAY['owner'::text, 'co_owner'::text, 'admin'::text]))))))","roles":["authenticated"],"tablename":"credit_requests","permissive":"PERMISSIVE","policyname":"credit_requests_update_manager","schemaname":"public","with_check":null},{"cmd":"SELECT","qual":"(( SELECT fn_is_any_union_overseer(( SELECT auth.uid() AS uid)) AS fn_is_any_union_overseer) AND fn_union_oversees_club(club_id, ( SELECT auth.uid() AS uid)))","roles":["authenticated"],"tablename":"credit_requests","permissive":"PERMISSIVE","policyname":"union_overseer_read","schemaname":"public","with_check":null}]$policies$::jsonb THEN RAISE EXCEPTION 'credit_request_policies_changed';END IF;
 IF (SELECT array_agg(a::text ORDER BY a::text) FROM pg_class c,LATERAL unnest(c.relacl) a
   WHERE c.oid='public.credit_requests'::regclass) IS DISTINCT FROM ARRAY['anon=arwdxtm/postgres','authenticated=arwdxtm/postgres','postgres=arwdDxtm/postgres','service_role=arwdDxtm/postgres']::text[]
 THEN RAISE EXCEPTION 'credit_request_acl_changed';END IF;
 IF (SELECT count(*) FROM pg_constraint WHERE conrelid='public.credit_requests'::regclass)<>1
 OR NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.credit_requests'::regclass
   AND contype='p' AND conkey=ARRAY[1]::smallint[] AND convalidated AND NOT condeferrable)
 THEN RAISE EXCEPTION 'credit_request_constraints_changed';END IF;
 IF (SELECT count(*) FROM pg_trigger WHERE tgrelid='public.credit_requests'::regclass AND NOT tgisinternal)<>1
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.credit_requests'::regclass
   AND tgname='trg_notify_credit_request' AND tgenabled='O' AND tgtype=21
   AND tgfoid='public.fn_notify_credit_request()'::regprocedure AND tgattr::text='8' AND tgqual IS NULL)
 THEN RAISE EXCEPTION 'credit_request_trigger_changed';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='public.fn_notify_credit_request()'::regprocedure
  AND md5(pg_get_functiondef(oid))='bce8aaeffc421ff88abdd31f428a5aaa' AND prosecdef AND pg_get_userbyid(proowner)='postgres')
 THEN RAISE EXCEPTION 'credit_request_notification_preimage_changed';END IF;
 -- This is a hash of the literal prosrc from the preceding source component,
 -- not a claimed measured post-install pg_get_functiondef hash.
 IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid='public.fn_admin_update_agent(uuid,text,text,numeric,numeric,numeric,uuid,text,boolean)'::regprocedure
  AND md5(prosrc)='d35ffecfde82d1d24582d95759ec4ed8' AND prosecdef AND pg_get_userbyid(proowner)='postgres')
 THEN RAISE EXCEPTION 'credit_request_requires_exact_150500_authority';END IF;
END $preimage$;

-- Untouched historical decisions remain explicitly unverified. Only this
-- authority may stamp version 1 in the same transaction as the reviewed limit.
ALTER TABLE public.credit_requests ADD COLUMN decision_authority_version smallint;

-- Existing INSERT/read scope remains. Clients can no longer independently
-- change a decision, recipient, review stamp or delete an issued request.
REVOKE UPDATE,DELETE,TRUNCATE,TRIGGER ON public.credit_requests FROM PUBLIC,anon,authenticated,service_role;
DO $columns$ DECLARE role_name text; column_name text; BEGIN
 FOREACH role_name IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
  FOR column_name IN SELECT attname FROM pg_attribute WHERE attrelid='public.credit_requests'::regclass AND attnum>0 AND NOT attisdropped LOOP
   EXECUTE format('REVOKE UPDATE (%I) ON public.credit_requests FROM %I',column_name,role_name);
  END LOOP;
 END LOOP;
END $columns$;
DROP POLICY credit_requests_update_manager ON public.credit_requests;

-- An agent cannot see every upline membership through roster RLS. This
-- INSERT-only private validator reads eligibility as owner without granting
-- roster access or changing the INVOKER terminal-decision caller fence.
CREATE FUNCTION public.fn_guard_credit_request_creation() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $function$
BEGIN
 IF NEW.status IS DISTINCT FROM 'pending' OR NEW.approved_amount IS NOT NULL OR NEW.reviewed_at IS NOT NULL
   OR NEW.reviewed_by IS NOT NULL OR NEW.reviewer_notes IS NOT NULL OR NEW.decision_authority_version IS NOT NULL
 THEN RAISE EXCEPTION 'credit_request_must_start_pending' USING ERRCODE='23514';END IF;
 IF auth.uid() IS NULL OR NEW.requester_id IS DISTINCT FROM auth.uid()
 THEN RAISE EXCEPTION 'credit_request_requester_identity_required' USING ERRCODE='42501';END IF;
 IF NEW.requested_amount IS NULL OR NEW.requested_amount::text IN('NaN','Infinity','-Infinity')
   OR NEW.requested_amount<=0 OR NEW.requested_amount<>round(NEW.requested_amount,2)
 THEN RAISE EXCEPTION 'credit_request_amount_must_be_positive_cents' USING ERRCODE='22023';END IF;
 IF (SELECT count(*) FROM public.agents a WHERE a.user_id=NEW.requester_id AND a.club_id=NEW.club_id)<>1
 THEN RAISE EXCEPTION 'credit_request_agent_scope_missing_or_ambiguous' USING ERRCODE='23514';END IF;
 IF NEW.approver_id IS NULL OR NEW.approver_id=NEW.requester_id
   OR NOT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=NEW.approver_id)
   OR NOT EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=NEW.club_id AND
     (c.owner_id=NEW.approver_id OR EXISTS(SELECT 1 FROM public.club_members m
       WHERE m.club_id=NEW.club_id AND m.user_id=NEW.approver_id
         AND m.role IN('owner','co_owner','admin') AND m.status IN('active','approved'))))
 THEN RAISE EXCEPTION 'credit_request_approver_invalid' USING ERRCODE='23514';END IF;
 RETURN NEW;
END $function$;
REVOKE ALL ON FUNCTION public.fn_guard_credit_request_creation() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER credit_request_creation_guard BEFORE INSERT ON public.credit_requests
 FOR EACH ROW EXECUTE FUNCTION public.fn_guard_credit_request_creation();

CREATE FUNCTION public.fn_guard_credit_request_decision() RETURNS trigger
LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $function$
BEGIN
 IF TG_OP='INSERT' THEN
  IF NEW.status IS DISTINCT FROM 'pending' OR NEW.approved_amount IS NOT NULL OR NEW.reviewed_at IS NOT NULL
    OR NEW.reviewed_by IS NOT NULL OR NEW.reviewer_notes IS NOT NULL OR NEW.decision_authority_version IS NOT NULL
  THEN RAISE EXCEPTION 'credit_request_must_start_pending' USING ERRCODE='23514';END IF;
 ELSE
  IF current_user<>'postgres' OR auth.uid() IS NULL
   OR current_setting('app.credit_request_decision',true) IS DISTINCT FROM OLD.id::text||':'||auth.uid()::text
   OR OLD.status IS DISTINCT FROM 'pending' OR OLD.decision_authority_version IS NOT NULL
   OR NEW.decision_authority_version IS DISTINCT FROM 1 OR NEW.status NOT IN('approved','denied','cancelled')
   OR NEW.reviewed_by IS DISTINCT FROM auth.uid() OR NEW.reviewed_at IS NULL
   OR (to_jsonb(NEW)-ARRAY['status','approved_amount','reviewed_at','reviewed_by','reviewer_notes','decision_authority_version'])
      IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','approved_amount','reviewed_at','reviewed_by','reviewer_notes','decision_authority_version'])
  THEN RAISE EXCEPTION 'credit_request_requires_atomic_decision' USING ERRCODE='42501';END IF;
 END IF;
 RETURN NEW;
END $function$;
REVOKE ALL ON FUNCTION public.fn_guard_credit_request_decision() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER credit_request_decision_guard BEFORE INSERT OR UPDATE ON public.credit_requests
 FOR EACH ROW EXECUTE FUNCTION public.fn_guard_credit_request_decision();

-- Every new request and decision inserts its notices through the existing
-- notification/outbox transaction. Missing or rewritten notices abort the
-- request/decision too. Replays do not update status or fire this trigger.
CREATE OR REPLACE FUNCTION public.fn_notify_credit_request() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $function$
DECLARE notification_id uuid;recipient uuid;recipients uuid[];
 notice_type text;notice_title text;notice_message text;notice_link text;
BEGIN
 IF TG_OP='INSERT' THEN
  recipients:=ARRAY[NEW.approver_id];notice_type:='credit_request';notice_title:='Credit Request';
  notice_message:=public.fn_notify_display_name(NEW.requester_id)||' requested '||round(NEW.requested_amount,2)::text||' chips credit';
  notice_link:='/credit-admin?club='||NEW.club_id::text;
 ELSIF TG_OP='UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN
  IF NEW.status='approved' THEN
   recipients:=ARRAY[NEW.requester_id];notice_type:='credit_approved';notice_title:='Credit Line Updated';
   notice_message:='Your credit line is now '||round(NEW.approved_amount,2)::text||' chips';notice_link:='/clubs/'||NEW.club_id::text||'/agent-dashboard';
  ELSIF NEW.status='denied' THEN
   recipients:=ARRAY[NEW.requester_id];notice_type:='credit_denied';notice_title:='Credit Request Denied';
   notice_message:=COALESCE(NULLIF(btrim(NEW.reviewer_notes),''),'Your credit request was not approved');notice_link:='/clubs/'||NEW.club_id::text||'/agent-dashboard';
  ELSIF NEW.status='cancelled' THEN
   SELECT array_agg(DISTINCT id ORDER BY id) INTO recipients
    FROM unnest(ARRAY[NEW.requester_id,NEW.approver_id]) AS ids(id) WHERE id IS NOT NULL;
   notice_type:='credit_cancelled';notice_title:='Credit Request Cancelled';
   notice_message:='This credit request was cancelled.';
  END IF;
 END IF;
 FOREACH recipient IN ARRAY COALESCE(recipients,ARRAY[]::uuid[]) LOOP
  IF recipient IS NULL THEN RAISE EXCEPTION 'credit_request_notification_missing' USING ERRCODE='23514';END IF;
  IF notice_type='credit_cancelled' THEN
   notice_link:=CASE WHEN recipient=NEW.requester_id THEN '/clubs/'||NEW.club_id::text||'/agent-dashboard'
    ELSE '/credit-admin?club='||NEW.club_id::text END;
  END IF;
  INSERT INTO public.notifications(user_id,type,title,message,link,data)
  VALUES(recipient,notice_type,notice_title,notice_message,notice_link,
   jsonb_build_object('creditRequestId',NEW.id,'clubId',NEW.club_id)) RETURNING id INTO notification_id;
  IF notification_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.notifications n
    WHERE n.id=notification_id AND n.user_id=recipient AND n.type=notice_type
      AND n.title=notice_title AND n.message=notice_message AND n.link=notice_link
      AND n.data->>'creditRequestId'=NEW.id::text AND n.data->>'clubId'=NEW.club_id::text)
  THEN RAISE EXCEPTION 'credit_request_notification_missing' USING ERRCODE='23514';END IF;
 END LOOP;
 RETURN NEW;
END $function$;
REVOKE ALL ON FUNCTION public.fn_notify_credit_request() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.fn_notify_credit_request() TO service_role;

CREATE FUNCTION public.fn_review_credit_request(p_request_id uuid,p_decision text,
 p_approved_amount numeric DEFAULT NULL,p_notes text DEFAULT NULL,p_expected_actor_id uuid DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public SET statement_timeout='30s' AS $function$
DECLARE actor uuid:=auth.uid(); scope_id uuid; request public.credit_requests%ROWTYPE;
 agent_ids uuid[]; amount numeric; notes text:=NULLIF(btrim(p_notes),''); result jsonb; old_context text;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'credit_request_authentication_required' USING ERRCODE='42501';END IF;
 IF p_expected_actor_id IS NULL OR p_expected_actor_id IS DISTINCT FROM actor THEN
  RAISE EXCEPTION 'credit_request_actor_changed' USING ERRCODE='42501';END IF;
 IF p_request_id IS NULL OR p_decision IS NULL OR p_decision NOT IN('approved','denied','cancelled')
 THEN RAISE EXCEPTION 'credit_request_invalid_decision' USING ERRCODE='22023';END IF;
 IF p_decision<>'approved' AND p_approved_amount IS NOT NULL
 THEN RAISE EXCEPTION 'credit_request_unexpected_approved_amount' USING ERRCODE='22023';END IF;
 SELECT club_id INTO scope_id FROM public.credit_requests WHERE id=p_request_id;
 IF scope_id IS NULL THEN RAISE EXCEPTION 'credit_request_missing' USING ERRCODE='22023';END IF;
 -- Same order as the canonical admin/role writers. Never hold a request row
 -- while waiting for a club agreement held by a competing financial update.
 PERFORM pg_advisory_xact_lock(hashtextextended('agent-agreement:'||scope_id::text,0));
 SELECT * INTO request FROM public.credit_requests WHERE id=p_request_id AND club_id=scope_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'credit_request_scope_changed' USING ERRCODE='23514';END IF;
 IF p_decision='cancelled' THEN
  IF actor IS DISTINCT FROM request.requester_id THEN
   RAISE EXCEPTION 'credit_request_only_requester_can_cancel' USING ERRCODE='42501';END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM public.clubs c WHERE c.id=scope_id AND
    (c.owner_id=actor OR EXISTS(SELECT 1 FROM public.club_members m WHERE m.club_id=scope_id AND m.user_id=actor
       AND m.role IN('owner','co_owner','admin') AND m.status IN('active','approved'))))
  THEN RAISE EXCEPTION 'credit_request_manager_required' USING ERRCODE='42501';END IF;
 END IF;
 amount:=CASE WHEN p_decision='approved' THEN COALESCE(p_approved_amount,request.requested_amount) END;
 IF p_decision='approved' AND (amount IS NULL OR amount::text IN('NaN','Infinity','-Infinity')
   OR amount<=0 OR amount<>round(amount,2))
 THEN RAISE EXCEPTION 'credit_request_amount_must_be_positive_cents' USING ERRCODE='22023';END IF;
 -- The request row itself is the durable decision identity. A later limit
 -- change is never rolled back by a retry of this already-completed request.
 IF request.status IS DISTINCT FROM 'pending' THEN
  IF request.decision_authority_version IS DISTINCT FROM 1 THEN
   RAISE EXCEPTION 'credit_request_legacy_review_unverified' USING ERRCODE='23514';END IF;
  IF request.status=p_decision AND request.reviewed_by=actor AND request.reviewed_at IS NOT NULL
    AND request.approved_amount IS NOT DISTINCT FROM amount
    AND NULLIF(btrim(request.reviewer_notes),'') IS NOT DISTINCT FROM notes
  THEN RETURN jsonb_build_object('success',true,'replayed',true,'request',to_jsonb(request)||jsonb_build_object('requested_amount',request.requested_amount::text,'approved_amount',request.approved_amount::text));END IF;
  RAISE EXCEPTION 'credit_request_decision_conflict' USING ERRCODE='23514';
 END IF;
 IF p_decision='approved' THEN
  SELECT array_agg(a.id ORDER BY a.id) INTO agent_ids FROM public.agents a
   WHERE a.club_id=scope_id AND a.user_id=request.requester_id;
  IF cardinality(agent_ids) IS DISTINCT FROM 1 THEN
   RAISE EXCEPTION 'credit_request_agent_scope_missing_or_ambiguous' USING ERRCODE='23514';END IF;
  result:=public.fn_admin_update_agent(p_agent_id=>agent_ids[1],p_credit_limit=>amount,
   p_assigned_by=>actor,p_credit_reason=>COALESCE(notes,'Credit request approved: '||request.id::text));
  IF result->>'success' IS DISTINCT FROM 'true' OR result->>'agent_id' IS DISTINCT FROM agent_ids[1]::text
    OR result->>'club_id' IS DISTINCT FROM scope_id::text OR (result->>'credit_limit')::numeric IS DISTINCT FROM amount
  THEN RAISE EXCEPTION 'credit_request_credit_authority_refused' USING ERRCODE='23514',DETAIL=result::text;END IF;
 END IF;
 old_context:=current_setting('app.credit_request_decision',true);
 PERFORM set_config('app.credit_request_decision',request.id::text||':'||actor::text,true);
 UPDATE public.credit_requests SET status=p_decision,approved_amount=amount,reviewed_by=actor,
  reviewed_at=transaction_timestamp(),reviewer_notes=notes,decision_authority_version=1 WHERE id=request.id AND status='pending'
  RETURNING * INTO request;
 IF NOT FOUND THEN RAISE EXCEPTION 'credit_request_decision_lost' USING ERRCODE='23514';END IF;
 PERFORM set_config('app.credit_request_decision',COALESCE(old_context,''),true);
 RETURN jsonb_build_object('success',true,'replayed',false,'request',to_jsonb(request)||jsonb_build_object('requested_amount',request.requested_amount::text,'approved_amount',request.approved_amount::text));
END $function$;
REVOKE ALL ON FUNCTION public.fn_review_credit_request(uuid,text,numeric,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.fn_review_credit_request(uuid,text,numeric,text,uuid) TO authenticated,service_role;
INSERT INTO public.ca_money_rpc_registry(proname,status,notes)
 VALUES('fn_review_credit_request','approved','Authenticated club manager review or own-request cancellation. Club agreement lock and pending decision fence; approves through fn_admin_update_agent in the same transaction, with mandatory terminal notification. Exact request decision replay returns its saved result without resetting later credit limits. No chip transfer or invoice payment.')
ON CONFLICT(proname) DO UPDATE SET status=EXCLUDED.status,notes=EXCLUDED.notes;
DO $authority$ DECLARE role_name text; column_name text; BEGIN
 FOREACH role_name IN ARRAY ARRAY['anon','authenticated','service_role'] LOOP
  IF has_function_privilege(role_name,'public.fn_guard_credit_request_creation()','EXECUTE')
   OR has_function_privilege(role_name,'public.fn_guard_credit_request_decision()','EXECUTE')
  THEN RAISE EXCEPTION 'credit_request_private_guard_executable: %',role_name;END IF;
  IF has_table_privilege(role_name,'public.credit_requests','UPDATE,DELETE,TRUNCATE,TRIGGER') THEN
   RAISE EXCEPTION 'credit_request_direct_writer_remains: %',role_name;END IF;
  FOR column_name IN SELECT attname FROM pg_attribute WHERE attrelid='public.credit_requests'::regclass AND attnum>0 AND NOT attisdropped LOOP
   IF has_column_privilege(role_name,'public.credit_requests',column_name,'UPDATE') THEN
    RAISE EXCEPTION 'credit_request_column_writer_remains: %.%',role_name,column_name;END IF;
  END LOOP;
 END LOOP;
END $authority$;

