}]$catalog$::jsonb) LOOP
  target:=to_regclass('public.'||(expected->>'name'));
  IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=target AND pg_get_userbyid(c.relowner)=expected->>'owner'
      AND c.relkind::text=expected->>'kind' AND c.relrowsecurity=(expected->>'rls')::boolean
      AND c.relforcerowsecurity=(expected->>'force_rls')::boolean AND c.relispartition=(expected->>'partition')::boolean
      AND c.relreplident::text=expected->>'replica_identity' AND to_jsonb(c.reloptions) IS NOT DISTINCT FROM NULLIF(expected->'options','null'::jsonb))
    OR EXISTS(SELECT 1 FROM pg_inherits WHERE target IN(inhparent,inhrelid))
  THEN RAISE EXCEPTION 'correction_writer_relation_preimage_changed' USING DETAIL=expected->>'name';END IF;
  SELECT jsonb_agg(a::text ORDER BY a::text) INTO actual FROM pg_class c,LATERAL unnest(c.relacl)a WHERE c.oid=target;
  IF actual IS DISTINCT FROM expected->'acl' THEN RAISE EXCEPTION 'correction_writer_relation_access_changed' USING DETAIL=expected->>'name';END IF;
  SELECT jsonb_agg(jsonb_build_object('name',a.attname,'ordinal',a.attnum,'type',format_type(a.atttypid,a.atttypmod),
    'not_null',a.attnotnull,'default',pg_get_expr(d.adbin,d.adrelid),'identity',a.attidentity,'generated',a.attgenerated,
    'acl',a.attacl,'collation',CASE WHEN a.attcollation<>0 THEN a.attcollation::regcollation::text END,
    'effective_privileges',(SELECT jsonb_object_agg(api,jsonb_build_object(
      'SELECT',has_column_privilege(api,target,a.attnum,'SELECT'),'INSERT',has_column_privilege(api,target,a.attnum,'INSERT'),
      'UPDATE',has_column_privilege(api,target,a.attnum,'UPDATE'),'REFERENCES',has_column_privilege(api,target,a.attnum,'REFERENCES')))
      FROM unnest(ARRAY['anon','authenticated','service_role'])api)) ORDER BY a.attnum)
   INTO actual FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
   WHERE a.attrelid=target AND a.attnum>0 AND NOT a.attisdropped;
  IF actual IS DISTINCT FROM expected->'columns' THEN RAISE EXCEPTION 'correction_writer_columns_changed' USING DETAIL=expected->>'name';END IF;
  SELECT jsonb_agg(jsonb_build_object('name',k.conname,'type',k.contype,'definition',pg_get_constraintdef(k.oid,true),
   'validated',k.convalidated,'deferrable',k.condeferrable,'initially_deferred',k.condeferred,
   'columns',k.conkey,'foreign_columns',k.confkey,'referenced_relation',CASE WHEN k.confrelid<>0 THEN k.confrelid::regclass::text END)
   ORDER BY k.conname) INTO actual FROM pg_constraint k WHERE k.conrelid=target;
  IF actual IS DISTINCT FROM expected->'constraints' THEN RAISE EXCEPTION 'correction_writer_constraints_changed' USING DETAIL=expected->>'name';END IF;
  SELECT jsonb_agg(jsonb_build_object('name',ci.relname,'definition',pg_get_indexdef(i.indexrelid),
   'owner',pg_get_userbyid(ci.relowner),'kind',ci.relkind,'unique',i.indisunique,'primary',i.indisprimary,
   'valid',i.indisvalid,'ready',i.indisready,'live',i.indislive,'immediate',i.indimmediate,
   'replica_identity',i.indisreplident,'clustered',i.indisclustered,'nulls_not_distinct',i.indnullsnotdistinct)
   ORDER BY ci.relname) INTO actual FROM pg_index i JOIN pg_class ci ON ci.oid=i.indexrelid WHERE i.indrelid=target;
  IF actual IS DISTINCT FROM expected->'indexes' THEN RAISE EXCEPTION 'correction_writer_indexes_changed' USING DETAIL=expected->>'name';END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('name',t.tgname,'definition',pg_get_triggerdef(t.oid,true),
