  IF actual IS DISTINCT FROM expected->'triggers' THEN RAISE EXCEPTION 'correction_writer_triggers_changed' USING DETAIL=expected->>'name';END IF;
  SELECT jsonb_agg(to_jsonb(p) ORDER BY p.policyname) INTO actual FROM pg_policies p WHERE p.schemaname='public' AND p.tablename=expected->>'name';
  IF actual IS DISTINCT FROM NULLIF(expected->'policies','null'::jsonb) THEN RAISE EXCEPTION 'correction_writer_policies_changed' USING DETAIL=expected->>'name';END IF;
  SELECT jsonb_object_agg(api,jsonb_build_object(
   'table',(SELECT jsonb_object_agg(priv,has_table_privilege(api,target,priv)) FROM unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE','REFERENCES','TRIGGER','MAINTAIN'])priv),
